            var stkTrust = scoresA[3] + scoresB[3] + scoresC[3];
            var stratAdapt = scoresA[4] + scoresB[4] + scoresC[4];

            var weighted = Math.round(
                bizPerf * 0.25 + scResil * 0.20 + polRisk * 0.20 +
                stkTrust * 0.20 + stratAdapt * 0.15
            );

            state.domainState.bizPerf += bizPerf;
            state.domainState.scResil += scResil;
            state.domainState.polRisk += polRisk;
            state.domainState.stkTrust += stkTrust;
            state.domainState.stratAdapt += stratAdapt;
            state.domainState.totalScore += weighted;

            state.domainState.bizPerfHistory.push(bizPerf);
            state.domainState.scResilHistory.push(scResil);
            state.domainState.polRiskHistory.push(polRisk);
            state.domainState.stkTrustHistory.push(stkTrust);
            state.domainState.stratAdaptHistory.push(stratAdapt);
            state.domainState.totalScoreHistory.push(weighted);

            // SCORE: overallScore is totalScore expressed as a percent of the max reachable
            // weighted total (rounds times 24, the same maxPossible getPerformanceSummary uses
            // for its performance bands), clamped to 0-100 so the last round matches that verdict
            var maxPossibleSoFar = this.ROUNDS.length * 24;
            var overallScore = Math.max(0, Math.min(100, Math.round(100 * state.domainState.totalScore / maxPossibleSoFar)));
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: overallScore });

            // FIX(v1.1.0): advance the briefing + decision menus synchronously
            // to the next round. The previous setTimeout closure read
            // state.currentPeriod AFTER the framework had incremented it, so it
            // jumped an extra round and desynced the shown scenario from the
            // scoring table. Guard on identity so the framework's deep-cloned
            // competition preview never mutates the live DOM.
            if (window.mySimulation && state === window.mySimulation.state) {
                var nextPeriod = (state.currentPeriod || 1) + 1;
                if (nextPeriod <= this.ROUNDS.length) {
                    this._updateBriefing({ currentPeriod: nextPeriod });
                }
            }

            return {
                period: state.currentPeriod,
                roundTitle: window.mySimulation.t(round.titleKey),
                bizPerf: bizPerf,
                scResil: scResil,
                polRisk: polRisk,
                stkTrust: stkTrust,
                stratAdapt: stratAdapt,
                weighted: weighted,
                cumBizPerf: state.domainState.bizPerf,
                cumScResil: state.domainState.scResil,
                cumPolRisk: state.domainState.polRisk,
                cumStkTrust: state.domainState.stkTrust,
                cumStratAdapt: state.domainState.stratAdapt,
                cumTotal: state.domainState.totalScore
            };
        }

