            // FIX(v1.1.0): the framework's undo restores domainState/decisions
            // but does not re-invoke the adapter view, leaving a stale briefing
            // and decision menus. Re-render on the framework's period:undone
            // event so the scenario always matches the reverted round.
            var self = this;
            var sim = window.mySimulation;
            if (sim && sim.eventBus && typeof sim.eventBus.on === 'function' && !this._undoBound) {
                this._undoBound = true;
                sim.eventBus.on('period:undone', function(st) {
