        getPerformanceSummary(history) {
            if (!history.length) return {};
            var totalWeighted = history.reduce(function(s, r) { return s + (r.results ? r.results.weighted : 0); }, 0);
            var avgWeighted = Math.round(totalWeighted / history.length);
            var maxPossible = 6 * 24;

            var performance = window.mySimulation.t('perf_developing');
            if (totalWeighted > maxPossible * 0.8) performance = window.mySimulation.t('perf_expert');
            else if (totalWeighted > maxPossible * 0.65) performance = window.mySimulation.t('perf_proficient');
            else if (totalWeighted > maxPossible * 0.5) performance = window.mySimulation.t('perf_competent');

            var insights = [];
            var totalBiz = history.reduce(function(s, r) { return s + (r.results ? r.results.bizPerf : 0); }, 0);
            var totalSC = history.reduce(function(s, r) { return s + (r.results ? r.results.scResil : 0); }, 0);
            var totalPol = history.reduce(function(s, r) { return s + (r.results ? r.results.polRisk : 0); }, 0);
            var totalStk = history.reduce(function(s, r) { return s + (r.results ? r.results.stkTrust : 0); }, 0);
            var totalStr = history.reduce(function(s, r) { return s + (r.results ? r.results.stratAdapt : 0); }, 0);

            var maxDim = Math.max(totalBiz, totalSC, totalPol, totalStk, totalStr);
            var minDim = Math.min(totalBiz, totalSC, totalPol, totalStk, totalStr);

            if (maxDim === totalSC) insights.push(window.mySimulation.t('insight_strong_sc'));
            if (maxDim === totalPol) insights.push(window.mySimulation.t('insight_strong_pol'));
            if (maxDim === totalStk) insights.push(window.mySimulation.t('insight_strong_stk'));
            if (maxDim === totalBiz) insights.push(window.mySimulation.t('insight_strong_biz'));
            if (maxDim === totalStr) insights.push(window.mySimulation.t('insight_strong_str'));

            if (minDim === totalBiz) insights.push(window.mySimulation.t('insight_weak_biz'));
            if (minDim === totalSC) insights.push(window.mySimulation.t('insight_weak_sc'));
            if (minDim === totalPol) insights.push(window.mySimulation.t('insight_weak_pol'));

            return {
                totalScore: totalWeighted,
                averageRound: avgWeighted,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.weighted < 16) return window.mySimulation.t('hint_low_score');
            if (results.bizPerf <= 14 && results.stkTrust >= 20) return window.mySimulation.t('hint_biz_weak');
            if (results.stkTrust <= 14) return window.mySimulation.t('hint_trust_weak');
            if (results.scResil <= 14) return window.mySimulation.t('hint_sc_weak');
            if (results.weighted >= 22) return window.mySimulation.t('hint_strong');
            return null;
        }

