        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            var t = window.mySimulation.t.bind(window.mySimulation);

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = t(round.briefingKey);

            var decALabel = document.getElementById('decALabel');
            if (decALabel) decALabel.textContent = t(round.decA.labelKey);

            var decBLabel = document.getElementById('decBLabel');
            if (decBLabel) decBLabel.textContent = t(round.decB.labelKey);

            var decCLabel = document.getElementById('decCLabel');
            if (decCLabel) decCLabel.textContent = t(round.decC.labelKey);

            this._rebuildSelect('decAInput', round.decA.options);
            this._rebuildSelect('decBInput', round.decB.options);
            this._rebuildSelect('decCInput', round.decC.options);
        }

        _rebuildSelect(selectId, options) {
            var sel = document.getElementById(selectId);
            if (!sel) return;
            sel.innerHTML = '';
            var t = window.mySimulation.t.bind(window.mySimulation);
            for (var i = 0; i < options.length; i++) {
                var opt = document.createElement('option');
                opt.value = (i + 1).toString();
                opt.textContent = t(options[i].textKey);
                sel.appendChild(opt);
            }
        }
    }

    document.addEventListener('DOMContentLoaded', function() {
        window.mySimulation = new USF.SimulationFramework();
        window.mySimulation.initialize(new GeoriskAdapter(), {
            simulationType: 'georisk_navigator',
            maxPeriods: 6,
            autoSaveInterval: 30000
        });
    });

})();
